import{z as o,x as s,o as e,c as m,q as A,j as n,D as E,d as t,s as l,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"不全市场","description":"","frontmatter":{"title":"不全市场","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/incomplete-market.md","filePath":"quant/incomplete-market.md","lastUpdated":1791063341000}'),p={name:"quant/incomplete-market.md"};function d(h,a,c,D,u,F){const B=s("Mermaid");return e(),m("div",null,[a[2]||(a[2]=A('<h1 id="不全市场" tabindex="-1">不全市场 <a class="header-anchor" href="#不全市场" aria-label="Permalink to &quot;不全市场&quot;">​</a></h1><div class="epigraph"><p>不完备时等价鞅测度是一整族。无套利只把价格钉在区间上；点价格需要额外选择，例如平方对冲或效用无差别。</p><footer>—— 据 Harrison and Pliska, 1983；Föllmer and Schweizer, Hedging of Contingent Claims, 1991；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/complete-unique-measure">完备市场与唯一测度</a>给出「\\(Q\\) 唯一则每个 \\(H\\) 可复制」。缺口是反过来：随机波动、跳、不可交易因子，都会留下无法对冲的余项。本课只说明价格变成区间、对冲变成投影，不把某种选取准则写成「正确价格」。主干后面的 BSM PDE 仍走完备；本课是对照，防止把唯一公式误用到不完备模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(\\mathcal M\\) 为等价鞅测度族，多于一点。对未定权益 \\(H\\)，每个 \\(Q\\in\\mathcal M\\) 给出一个无套利候选 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\)。无套利价格的全体是这些期望的区间（在凸、闭的技术条件下）。报区间之外的价，可被可容许策略套利；报区间之内，无法用可交易资产复制来锁定。缺口不是再找一个 Girsanov \\(\\theta\\)，而是承认 \\(\\theta\\) 的不可对冲分量自由。</p><p><span class="marginnote">价格区间可以类比二手车的「收购价—标价」：无套利只保证你不该在区间之外成交；区间内具体报哪个数，取决于做市商愿意承受多少无法对冲的剩余风险。</span></p><p>常见来源：Heston 的方差过程不可交易；Merton 跳的跳幅测度不能被连续交易完全对冲；多因子利率只交易部分债券。本课程不展开这些模型的闭式，只留「多个 \\(Q\\)」的接口。</p><h3 id="不全不是「没有风险中性测度」" tabindex="-1">不全不是「没有风险中性测度」 <a class="header-anchor" href="#不全不是「没有风险中性测度」" aria-label="Permalink to &quot;不全不是「没有风险中性测度」&quot;">​</a></h3><p>第一基本定理仍然要存在至少一个 \\(Q\\)，否则有套利。不全是存在但不唯一。把「随机波动」说成「不能风险中性定价」，漏掉了：可以定价，只是要额外选 \\(Q\\)，或接受区间。</p><p><span class="marginnote">最小鞅测度、方差最优对冲，是在 \\(\\mathcal M\\) 里挑一个投影。它们是选择，不是市场给出的唯一价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>超对冲价格 \\(\\inf\\{V_0:\\) 存在策略终值 \\(\\ge H\\}\\) 等于 \\(\\sup_{Q\\in\\mathcal M}\\mathrm e^{-rT}\\mathbb E_Q[H]\\)；次对冲是对偶的 \\(\\inf\\)。可复制的 \\(H\\) 使两端重合。对一般 \\(H\\)，复制误差 \\(H-V_T^{\\Delta}\\) 正交于可交易增益子空间（Föllmer–Schweizer 的意义下），剩余风险不能靠加交易消掉。区间内部的报价可以成交，但不能被复制锁定；做市商报点价时，其实是在区间里选了一点并自己承担残差。</p><p>实践接口：若把不可交易因子的市场价格外生给定（例如方差风险溢价写成参数），就从 \\(\\mathcal M\\) 里挑出一点，公式看起来又像完备。那是额外经济假设，必须写明；不能假装第二基本定理仍然成立。</p><p><span class="marginnote">初学者容易以为「随机波动模型也能写出期权公式」就等于市场完备。公式能算，只是因为你把方差风险溢价当成了已知参数；换一组参数价格就不同。这不是市场给出的唯一答案，而是你替市场做了一个额外假设。</span></p>',14)),(e(),n(i,null,{default:E(()=>[l(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAM%5B%22%E9%9E%85%E6%B5%8B%E5%BA%A6%E6%97%8F%22%5D%20--%3E%20INTV%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%E4%BB%B7%E6%A0%BC%E5%8C%BA%E9%97%B4%22%5D%0A%20%20INTV%20--%3E%20SUPER%5B%22%E8%B6%85%E5%AF%B9%E5%86%B2%E4%B8%8A%E7%AB%AF%22%5D%0A%20%20INTV%20--%3E%20SUB%5B%22%E6%AC%A1%E5%AF%B9%E5%86%B2%E4%B8%8B%E7%AB%AF%22%5D%0A%20%20FAM%20--%3E%20PICK%5B%22%E5%A4%96%E7%94%9F%E9%80%89%E5%AE%9A%E4%B8%80%E4%B8%AA%20Q%22%5D%0A%20%20PICK%20--%3E%20FK%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9AFeynman-Kac%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"不可对冲的噪声在 Girsanov 里对应自由的 \\(\\theta\\) 分量：它改 \\(H\\) 的分布，但不改可交易贴现资产的鞅性质。因此 \\(\\mathbb E_Q[H]\\) 随 \\(Q\\) 动，而可交易资产的当前价不动。区间宽度衡量剩余风险有多大。完备市场宽度为零。把随机波动的市场价格写成常数参数，等于人为把宽度压成一点——公式能算，但第二基本定理并未恢复。",-1)),(e(),n(i,null,{default:E(()=>[l(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%8D%E5%8F%AF%E5%AF%B9%E5%86%B2%E5%99%AA%E5%A3%B0%3A%20%E6%96%B9%E5%B7%AE%20%2F%20%E8%B7%B3%20%2F%20%E4%B8%8D%E5%8F%AF%E4%BA%A4%E6%98%93%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20FREE%5B%22Girsanov%20%E4%B8%AD%E8%87%AA%E7%94%B1%E7%9A%84%20%CE%B8%20%E5%88%86%E9%87%8F%22%5D%0A%20%20FREE%20--%3E%20HMOVE%5B%22E_Q%5BH%5D%20%E9%9A%8F%E9%80%89%E7%9A%84%20Q%20%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20FREE%20--%3E%20FIXED%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E8%B5%84%E4%BA%A7%E5%BD%93%E5%89%8D%E4%BB%B7%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20HMOVE%20--%3E%20WIDTH%5B%22%E5%8C%BA%E9%97%B4%E5%AE%BD%E5%BA%A6%20%3D%20%E5%89%A9%E4%BD%99%E9%A3%8E%E9%99%A9%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20FIXED%20--%3E%20WIDTH%0A%20%20WIDTH%20--%3E%20ZERO%5B%22%E5%AE%8C%E5%A4%87%E5%B8%82%E5%9C%BA%3A%20%E5%AE%BD%E5%BA%A6%E4%B8%BA%E9%9B%B6%2C%20Q%20%E5%94%AF%E4%B8%80%22%5D%0A%20%20WIDTH%20--%3E%20FORCE%5B%22%E4%BA%BA%E4%B8%BA%E9%92%89%E6%AD%BB%E6%96%B9%E5%B7%AE%E6%BA%A2%E4%BB%B7%3A%20%E5%AE%BD%E5%BA%A6%E8%A2%AB%E5%8E%8B%E6%88%90%E4%B8%80%E7%82%B9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p>效用无差别价格把挑选 \\(Q\\) 写成优化：不同效用给出不同点。这不是本课程主干。主干在 BSM 里回到唯一 \\(Q\\)，以便 PDE 与 delta 有单一对象。</p><p><span class="marginnote">「效用无差别定价」就是「我最多愿意为这份合约付多少钱，使得付完之后我的满足感不比不买时差」。不同人的效用函数不同，报出的点就不同——这正是区间内选点的一种具体办法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导 Heston 的特征函数，不写跳扩散的 Esscher 选取，不进入不完全市场的均衡定价。美式、跳、MC 只在后面给接口。后课默认：写 Black–Scholes 公式时市场被当作完备；遇到随机波动或跳，先问 \\(Q\\) 是否被额外假设钉死。主干定价数学不靠把不全市场「校准成」唯一公式来回避区间。下一课<a href="/quant/feynman-kac">Feynman–Kac</a>在扩散设定下把期望变回 PDE，默认已有一个用来取期望的测度。区间问题到此暂停，不带进 PDE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不完备 \\(\\Leftrightarrow\\) 多个等价鞅测度。</li><li>无套利给出价格区间，不是一个点。</li><li>点价格需要外生选择，不是第二基本定理。</li><li>存在 \\(Q\\) 仍必要；不全不是没有 \\(Q\\)。</li><li>效用无差别与最小鞅测度都是选点，不是市场唯一价。</li><li>出处：Harrison–Pliska 1983；Föllmer–Schweizer 1991。</li></ul>',6))])}const T=o(p,[["render",d]]);export{f as __pageData,T as default};
